/**
 * Cross-platform test: verifies that headerVerify.js (Web Crypto) can correctly
 * accept/reject a password against a header produced by the Java ProperCrypto class.
 *
 * The fixture file was generated by GenerateFixture.java:
 *   password = "fixture_password_2026"
 *   plaintext = "Hello from ProperBackup Java crypto!"
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { join, dirname } from 'path';
import { verifyPassword, parseHeader, BadPasswordError, InvalidFileError } from './headerVerify.js';

const __dir = dirname(fileURLToPath(import.meta.url));
const fixturePath = join(__dir, '../fixtures/mock-encrypted-headers.bin');
// Node's Buffer shares an underlying ArrayBuffer pool; slice to get an exact copy.
const _nodeBuf = readFileSync(fixturePath);
const fixtureBytes = _nodeBuf.buffer.slice(_nodeBuf.byteOffset, _nodeBuf.byteOffset + _nodeBuf.byteLength);

const CORRECT_PASSWORD = 'fixture_password_2026';

describe('headerVerify — cross-platform Java↔JS', () => {
  it('accepts correct password against Java-produced header', async () => {
    await expect(verifyPassword(CORRECT_PASSWORD, fixtureBytes)).resolves.toBeUndefined();
  });

  it('rejects wrong password with BadPasswordError', async () => {
    await expect(verifyPassword('wrong_password', fixtureBytes))
      .rejects.toBeInstanceOf(BadPasswordError);
  });

  it('rejects empty password', async () => {
    await expect(verifyPassword('', fixtureBytes))
      .rejects.toBeInstanceOf(BadPasswordError);
  });
});

describe('parseHeader', () => {
  it('parses magic, salt, nonce, authTag correctly', () => {
    const h = parseHeader(fixtureBytes);
    expect(h.salt.length).toBe(16);
    expect(h.nonce.length).toBe(12);
    expect(h.authTag.length).toBe(16);
  });

  it('throws InvalidFileError on wrong magic', () => {
    const bad = new Uint8Array(49);
    bad[0] = 0x00;
    expect(() => parseHeader(bad.buffer)).toThrow(InvalidFileError);
  });

  it('throws InvalidFileError on buffer too small', () => {
    expect(() => parseHeader(new ArrayBuffer(10))).toThrow(InvalidFileError);
  });

  it('throws InvalidFileError on wrong version byte', () => {
    const data = new Uint8Array(fixtureBytes.slice(0, 49));
    data[4] = 0x02;
    expect(() => parseHeader(data.buffer)).toThrow(InvalidFileError);
  });
});
